// Counts primes <= N using Lucy_Hedgehog's O(N^(3/4)) algorithm.
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <math.h>

int main(int argc, char **argv) {
    uint64_t n = argc > 1 ? strtoull(argv[1], 0, 10) : 999999999ULL; // primes below 1e9
    uint32_t r = (uint32_t)sqrt((double)n);
    while ((uint64_t)r * r > n) r--;
    while ((uint64_t)(r + 1) * (r + 1) <= n) r++;

    uint32_t *lo = malloc((r + 2) * sizeof *lo); // lo[i] = count for value i
    uint32_t *hi = malloc((r + 2) * sizeof *hi); // hi[i] = count for value n/i
    for (uint32_t i = 1; i <= r; i++) {
        lo[i] = i - 1;
        hi[i] = (uint32_t)(n / i - 1);
    }
    for (uint32_t p = 2; p <= r; p++) {
        if (lo[p] == lo[p - 1]) continue;
        uint32_t pc = lo[p - 1];
        uint64_t p2 = (uint64_t)p * p;
        uint32_t end = (uint32_t)(n / p2 < r ? n / p2 : r);
        uint32_t split = r / p < end ? r / p : end;
        uint32_t i = 1;
        for (; i <= split; i++) hi[i] -= hi[i * p] - pc;
        for (; i <= end; i++) hi[i] -= lo[(uint32_t)(n / ((uint64_t)i * p))] - pc;
        for (uint32_t j = r; j >= p2; j--) lo[j] -= lo[j / p] - pc;
    }
    printf("%u\n", hi[1]);
    return 0;
}
