// Accepted date layouts, tried in order.
var dateLayouts = []string{
	"2006-01-02",
	"2006-01-02 15:04:05",
	time.RFC3339,
	"01/02/2006",
	"2/1/2006",
}

type key struct {
	month  string // YYYY-MM
	region string
}

func parseDate(s string) (time.Time, error) {
	s = strings.TrimSpace(s)
	for _, layout := range dateLayouts {
		if t, err := time.Parse(layout, s); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("unrecognized date %q", s)
}

// parseCents converts an amount like "1,234.56" or "$99.5" to integer cents,
// avoiding float accumulation error when summing.
func parseCents(s string) (int64, error) {
	s = strings.TrimSpace(s)
	s = strings.NewReplacer(",", "", "$", "").Replace(s)
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, err
	}
	return int64(math.Round(f * 100)), nil
}

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s sales.csv\n", os.Args[0])
		os.Exit(2)
	}

	f, err := os.Open(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()

	r := csv.NewReader(f)
	header, err := r.Read()
	if err != nil {
		fmt.Fprintln(os.Stderr, "reading header:", err)
		os.Exit(1)
	}

	// Locate columns by name so column order doesn't matter.
	idx := map[string]int{}
	for i, h := range header {
		idx[strings.ToLower(strings.TrimSpace(h))] = i
	}
	di, ok1 := idx["date"]
	ri, ok2 := idx["region"]
	ai, ok3 := idx["amount"]
	if !ok1 || !ok2 || !ok3 {
		fmt.Fprintln(os.Stderr, "header must contain date, region, amount")
		os.Exit(1)
	}

	totals := map[key]int64{}
	line := 1
	for {
		rec, err := r.Read()
		if err == io.EOF {
			break
		}
		line++
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", line, err)
			continue
		}
		t, err := parseDate(rec[di])
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: %v\n", line, err)
			continue
		}
		cents, err := parseCents(rec[ai])
		if err != nil {
			fmt.Fprintf(os.Stderr, "line %d: bad amount %q\n", line, rec[ai])
			continue
		}
		k := key{t.Format("2006-01"), strings.TrimSpace(rec[ri])}
		totals[k] += cents
	}

	keys := make([]key, 0, len(totals))
	for k := range totals {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].month != keys[j].month {
			return keys[i].month < keys[j].month
		}
		return keys[i].region < keys[j].region
	})

	w := csv.NewWriter(os.Stdout)
	defer w.Flush()
	w.Write([]string{"month", "region", "total"})
	for _, k := range keys {
		c := totals[k]
		w.Write([]string{k.month, k.region, fmt.Sprintf("%d.%02d", c/100, c%100)})
	}
}
